codeExample:
.header {
  position: sticky;
  top: 0;
  background: white;
  border-bottom: 1px solid #ddd;
  padding: 12px;
  z-index: 10;
}

.badge {
  display: inline-block;
  padding: 4px 8px;
  background: #e8fff8;
}

.modal {
  position: fixed;
  top: 20%;
  left: 50%;
  transform: translateX(-50%);
  background: white;
  border: 1px solid #ccc;
  padding: 20px;
}
